// Exact released source with authentic ABI declarations.
typedef float time_value_t;
typedef unsigned short signal_id_t;

struct string_buf { unsigned long long *data; int ref_count; int char_length; int block_length; int max_blocks; };
class stringx {
  char *chars; string_buf *my_buf;
public:
  stringx(); stringx(const stringx &); stringx(const char *, int = -1); ~stringx();
  const char *c_str() const { return chars; }
  int size() const { return my_buf->char_length; }
  stringx substr(int, int) const;
  void make_room(int); void append(const char *, int); void append(const stringx &);
  stringx &operator+=(const char *s) { extern unsigned int strlen(const char *); int n=strlen(s); make_room(size()+n); append(s,n); return *this; }
  stringx &operator+=(const stringx &s) { make_room(size()+s.size()); append(s); return *this; }
};
inline stringx operator+(const char *a, const stringx &b) { stringx r; r += a; r += b; return r; }
inline stringx operator+(const stringx &a, const char *b) { stringx r; r += a; r += b; return r; }

class camera { public: static signal_id_t get_signal_id(const char *); };
class entity { public: static signal_id_t get_signal_id(const char *); };
class marker { public: static signal_id_t get_signal_id(const char *); };
class mic { public: static signal_id_t get_signal_id(const char *); };
class light_source { public: static signal_id_t get_signal_id(const char *); };
class particle_generator { public: static signal_id_t get_signal_id(const char *); };
class item { public: static signal_id_t get_signal_id(const char *); };
class conglomerate { public: static signal_id_t get_signal_id(const char *); };
class beam { public: static signal_id_t get_signal_id(const char *); };

enum entity_flavor_t { ENTITY_CAMERA, ENTITY_ENTITY, ENTITY_MARKER, ENTITY_MIC, ENTITY_LIGHT_SOURCE, ENTITY_PARTICLE_GENERATOR, ENTITY_ITEM, ENTITY_CONGLOMERATE, ENTITY_BEAM, ENTITY_PHYSICAL, ENTITY_MOBILE, ENTITY_LIGHT, ENTITY_UNUSED12, NUM_ENTITY_FLAVORS=21, IGNORE_FLAVOR=22 };
extern const char *entity_flavor_names[NUM_ENTITY_FLAVORS];
void error(const stringx &);

class signal_key {
  time_value_t timestamp; unsigned int values;
public:
  signal_key(time_value_t t): timestamp(t), values(0) {}
  void add_value(signal_id_t s) { values |= 1 << s; }
};
class signal_track {
  int padding[2];
public:
  int num_signals; signal_key *signals;
  void add_key(time_value_t, entity_flavor_t, stringx);
};

void signal_track::add_key( time_value_t timestamp, entity_flavor_t entity_flavor, stringx signaldata )
{
  signal_id_t s = 0;
  int idx = 0;
  signal_key* key_pt = 0;

  while( 1 )
  {
    const char *currname = signaldata.c_str();
    int curridx;

    while( currname[idx] == '\n' || currname[idx] == '\r' )
      idx++;

    curridx = idx;

    while( currname[idx] && currname[idx] != '\n' && currname[idx] != '\r' )
      idx++;

    stringx oneline = signaldata.substr( curridx, idx-curridx );

    if( oneline.size() )
    {
      switch( entity_flavor )
      {
        case ENTITY_CAMERA: s = camera::get_signal_id( oneline.c_str() ); break;
        case ENTITY_ENTITY: s = entity::get_signal_id( oneline.c_str() ); break;
        case ENTITY_MARKER: s = marker::get_signal_id( oneline.c_str() ); break;
        case ENTITY_MIC: s = mic::get_signal_id( oneline.c_str() ); break;
        case ENTITY_LIGHT_SOURCE: s = light_source::get_signal_id( oneline.c_str() ); break;
        case ENTITY_PARTICLE_GENERATOR: s = particle_generator::get_signal_id( oneline.c_str() ); break;
        case ENTITY_ITEM: s = item::get_signal_id( oneline.c_str() ); break;
        case ENTITY_CONGLOMERATE: s = conglomerate::get_signal_id( oneline.c_str() ); break;
        case ENTITY_BEAM: s = beam::get_signal_id( oneline.c_str() ); break;
        case ENTITY_PHYSICAL:
        case ENTITY_MOBILE:
        case ENTITY_LIGHT: s = (unsigned short)-1; break;
        default: break;
      }

      if( s == (signal_id_t)-1 )
      {
        stringx name( currname );
        error( "Unknown signal " + name + " for entity " + entity_flavor_names[entity_flavor] );
      }

      if( !key_pt )
        key_pt = new(0, "C:/KS/SRC/signal_anim.cpp", 0) signal_key( timestamp );

      key_pt->add_value( s );
    }

    if( !currname[idx] )
      break;
  }

  if( key_pt )
  {
    signals[ num_signals ] = *key_pt;
    num_signals++;
    delete key_pt;
  }
}
